// Package apiconv converts ent entities into the ogen-generated API DTOs.
//
// The per-field struct mapping is generated by goverter (apiconv.gen.go). Only
// the irreducible bridges for ogen's Nil* wrapper types (which are custom value
// types goverter cannot infer) are declared here as extends — written once and
// reused by every generated mapping.
package apiconv

import (
	"path/filepath"
	"slices"
	"strings"
	"time"

	"github.com/lib/pq"
	"github.com/samber/lo"
	"gopkg.in/yaml.v3"

	"hexletbasics/ent"
	"hexletbasics/internal/api"
	"hexletbasics/internal/assetstore"
	"hexletbasics/internal/blogposts"
	"hexletbasics/internal/dashboard"
	"hexletbasics/internal/progress"
)

//go:generate go tool goverter gen hexletbasics/internal/apiconv

// Converter maps ent rows to the generated API DTOs.
//
// goverter:converter
// goverter:output:file ./apiconv.gen.go
// goverter:useZeroValueOnPointerInconsistency yes
// goverter:extend Int32FromInt
// goverter:extend Int32FromPtr
// goverter:extend StringFromPtr
// goverter:extend NilStringFromPtr
// goverter:extend NilInt32FromPtr
// goverter:extend NilBoolFromPtr
// goverter:extend NilDateTimeFromPtr
// goverter:extend NilLearnAsFromPtr
// goverter:extend NilReadinessFromPtr
// goverter:extend NilReviewStateFromPtr
// goverter:extend NilReviewLocaleFromPtr
// goverter:extend NilLandingPageStateFromPtr
// goverter:extend PermissionResourceFromString
// goverter:extend LocalesFromPq
// goverter:extend NilCourseVersionFromEnt
// goverter:extend NilEnrollmentStateFromPtr
// goverter:extend NilEnrollmentStateFromString
// goverter:extend TimeIdentity
// goverter:extend EnrollmentStateFromPtr
// goverter:extend LocaleFromPtr
// goverter:extend NilBlogPostStateFromPtr
// goverter:extend NilStringFromEmpty
type Converter interface {
	ToCatalogItems(source []*ent.CourseLandingPage) []api.CourseCatalogItem

	// goverter:map Edges.Course Course
	// goverter:map Edges.Course.EnrollmentsCount EnrollmentsCount
	// goverter:map . CoverUrl | coverURLNull
	// goverter:ignore Duration
	ToCatalogItem(source *ent.CourseLandingPage) api.CourseCatalogItem

	// Every api.Course field maps from real ent data, mirroring LanguageResource:
	// direct columns (createdAt, currentVersionId, hexletProgramLandingPage), the
	// current_version association, and the serializer's computed fields as bridges
	// below. Only the ActiveStorage cover variants stay deferred (same reason as
	// CourseCatalogItem.CoverUrl — blob assets are not migrated yet).
	// goverter:map CategoryID CategoryId
	// goverter:map CurrentVersionID CurrentVersionId
	// goverter:map Edges.CurrentVersion CurrentVersion
	// goverter:map . RepositoryUrl | repositoryURL
	// goverter:map . HexletProgramLandingPage | hexletProgramLandingPage
	// goverter:map . RatingCount | ratingCount
	// goverter:map . RatingValue | ratingValue
	// goverter:map . CoverListVariant | coverVariantNull
	// goverter:map . CoverThumbVariant | coverVariantNull
	ToCourse(source *ent.Course) api.Course

	ToCourses(source []*ent.Course) []api.Course

	// The sitemap's slim rows (legacy Sitemap*Resource): only what a link needs.
	// goverter:map CourseID CourseId
	ToSitemapCourseLandingPage(source *ent.CourseLandingPage) api.SitemapCourseLandingPage

	ToSitemapCourseLandingPages(source []*ent.CourseLandingPage) []api.SitemapCourseLandingPage

	// A blog post as the reader assembled it (creator loaded): the reader owns
	// the cover URL, the likes and the reading time, so this is a field copy.
	// goverter:map RichBody RichBodyHtml
	// goverter:map RelatedCourseIDs RelatedCourseIds
	// goverter:map CoverURL CoverUrl
	ToBlogPost(source blogposts.Post) api.BlogPost

	ToBlogPosts(source []blogposts.Post) []api.BlogPost

	ToSitemapBlogPost(source *ent.BlogPost) api.SitemapBlogPost

	ToSitemapBlogPosts(source []*ent.BlogPost) []api.SitemapBlogPost

	ToCourseCategory(source *ent.CourseCategory) api.CourseCategory

	ToCourseCategories(source []*ent.CourseCategory) []api.CourseCategory

	ToBanner(source *ent.Banner) api.Banner

	ToAttachment(source assetstore.Attachment) api.Attachment

	ToBanners(source []*ent.Banner) []api.Banner

	// Lead.FullName is derived from the associated user in the legacy serializer;
	// until the User schema lands it stays null (contract allows it). UserID
	// carries the DB casing, so it is mapped explicitly to the api's UserId.
	// goverter:map UserID UserId
	// goverter:map . FullName | leadFullNameNull
	ToLead(source *ent.Lead) api.Lead

	ToLeads(source []*ent.Lead) []api.Lead

	// UserCrud is the admin list/form projection of a user: id + the four
	// directly-editable columns. All fields map by name from the ent row.
	ToUserCrud(source *ent.User) api.UserCrud

	ToUserCruds(source []*ent.User) []api.UserCrud

	// User is the rich serializer projection (mirrors UserResource): the direct
	// columns plus the computed name, can_access_admin, created_at timestamp and
	// the constant "user" type discriminator.
	// goverter:map . Name | userName
	// goverter:map . CanAccessAdmin | userCanAccessAdmin
	// goverter:map . CreatedAtAsTimestamp | userCreatedAtAsTimestamp
	// goverter:map . Type | userType
	ToUser(source *ent.User) api.User

	// PublicUser is the anonymous-safe user projection: id and display name, with
	// no email or admin flag, for the public review and blog responses.
	// goverter:map . Name | userName
	ToPublicUser(source *ent.User) api.PublicUser

	// Review embeds the full course and user (loaded via WithCourse/WithUser).
	// courseId is the legacy `language_id` column; full_name joins the review's
	// own first/last name (mirrors ReviewResource#full_name).
	// goverter:map Edges.Course Course
	// goverter:map Edges.User User
	// goverter:map CourseID CourseId
	// goverter:map UserID UserId
	// goverter:map . FullName | reviewFullName
	ToReview(source *ent.Review) api.Review

	ToReviews(source []*ent.Review) []api.Review

	// QnA items (category + landing page) share the flat {id, question, answer}
	// projection; the nullable ent columns resolve to required strings.
	ToCategoryQnaItem(source *ent.CategoryQnaItem) api.QnaItem

	ToCategoryQnaItems(source []*ent.CategoryQnaItem) []api.QnaItem

	ToLandingPageQnaItem(source *ent.LandingPageQnaItem) api.QnaItem

	ToLandingPageQnaItems(source []*ent.LandingPageQnaItem) []api.QnaItem

	// CourseLandingPage is the admin projection of a landing page. courseSlug,
	// duration and membersCount come from the associated course (loaded via
	// WithCourse); outcomesImage stays null until blob assets are migrated (same
	// deferral as the course cover). Required-string fields resolve from nullable
	// columns via StringFromPtr.
	// goverter:map CourseID CourseId
	// goverter:map LandingPageToRedirectID LandingPageToRedirectId
	// goverter:map Edges.Course.Slug CourseSlug
	// goverter:map Edges.Course.EnrollmentsCount EnrollmentsCount
	// goverter:map Edges.Course Duration | courseDuration
	// goverter:map . OutcomesImage | landingOutcomesImageNull
	ToCourseLandingPage(source *ent.CourseLandingPage) api.CourseLandingPage

	ToCourseLandingPages(source []*ent.CourseLandingPage) []api.CourseLandingPage

	// StaffRole is the list projection: permissionsCount is the size of the
	// loaded permissions edge.
	// goverter:map . PermissionsCount | staffRolePermissionsCount
	ToStaffRole(source *ent.StaffRole) api.StaffRole

	ToStaffRoles(source []*ent.StaffRole) []api.StaffRole

	// StaffRoleDetail carries the full permission matrix (loaded via
	// WithPermissions) and the declared Permissions it holds (WithGrants).
	// goverter:map Edges.Permissions Permissions
	// goverter:map Edges.Grants Grants | grantNames
	ToStaffRoleDetail(source *ent.StaffRole) api.StaffRoleDetail

	// goverter:map RoleID RoleId
	ToStaffRolePermission(source *ent.StaffRolePermission) api.StaffRolePermission

	// StaffMember embeds the full user and role (loaded via WithUser/WithRole);
	// allowedLocales is the native pg array bridged by LocalesFromPq.
	// goverter:map UserID UserId
	// goverter:map RoleID RoleId
	// goverter:map Edges.User User
	// goverter:map Edges.Role Role
	ToStaffMember(source *ent.StaffMember) api.StaffMember

	ToStaffMembers(source []*ent.StaffMember) []api.StaffMember

	// Lesson list rows are version infos with the stable lesson identity loaded
	// through WithLesson.
	// goverter:map CourseLessonID ID
	// goverter:map Edges.Lesson.Slug Slug
	ToCourseLessonListItem(source *ent.CourseLessonTranslation) api.CourseLessonListItem

	ToCourseLessonListItems(source []*ent.CourseLessonTranslation) []api.CourseLessonListItem

	// Lesson progress projections require WithCourse and WithLesson; the lesson
	// query additionally eager-loads locale-filtered infos in ascending id order.
	// goverter:map UserID UserId
	// goverter:map Edges.Course.Slug CourseSlug
	// goverter:map Edges.Lesson.Slug CourseLessonSlug
	// goverter:map . CourseLessonName | lessonProgressLessonName
	ToLessonProgress(source *ent.LessonProgress) api.LessonProgress

	ToLessonProgressList(source []*ent.LessonProgress) []api.LessonProgress

	// Assistant messages are the admin read model over `ai_messages` (legacy
	// AiMessageResource). Course/lesson identity travels through
	// chat → lesson progress → course/lesson; the handler eager-loads the
	// lesson's locale-filtered infos so the name resolves like the lesson
	// progress list.
	// goverter:map UserID UserId
	// goverter:map Edges.Chat.Edges.LessonProgress.Edges.Course.Slug CourseSlug
	// goverter:map Edges.Chat.Edges.LessonProgress.Edges.Lesson.Slug CourseLessonSlug
	// goverter:map . CourseLessonName | assistantMessageLessonName
	ToLessonAssistantMessage(source *ent.AiMessage) api.LessonAssistantMessage

	ToLessonAssistantMessages(source []*ent.AiMessage) []api.LessonAssistantMessage

	// Review projections require WithCourse and WithLesson.
	// goverter:map CourseID CourseId
	// goverter:map CourseLessonID CourseLessonId
	// goverter:map CourseLessonVersionID CourseLessonVersionId
	// goverter:map CourseLessonTranslationID CourseLessonVersionInfoId
	// goverter:map Edges.Lesson.Slug Slug
	// goverter:map Edges.Lesson.NaturalOrder LessonNaturalOrder
	// goverter:map Edges.Course.Slug CourseSlug
	ToCourseLessonReview(source *ent.CourseLessonReview) api.CourseLessonReview

	ToCourseLessonReviews(source []*ent.CourseLessonReview) []api.CourseLessonReview

	// An Enrollment is the record alone: where the learner stands in it is
	// computed against the current Version and travels as CourseProgress.
	// goverter:map UserID UserId
	// goverter:map CourseID CourseId
	ToEnrollment(source *ent.Enrollment) api.Enrollment

	// The computed course state. The Next Lesson is named from the lessons of the
	// visitor's locale (nextLessonOf); the state knows only its slug.
	// goverter:map State.State State
	// goverter:map State.Completion Completion
	// goverter:map . NextLesson | nextLessonOf
	ToCourseProgress(source CourseProgressSource) api.CourseProgress

	// The dashboard names the Next Lesson itself (its id and name came from the
	// request locale's translations), so its progress is a different projection.
	// goverter:map State.State State
	// goverter:map State.Completion Completion
	// goverter:map . NextLesson | dashboardNextLesson
	ToDashboardProgress(source dashboard.Course) api.CourseProgress

	// goverter:map . Progress
	ToDashboardCourse(source dashboard.Course) api.DashboardCourse

	ToDashboardCourses(source []dashboard.Course) []api.DashboardCourse

	// A lesson with the visitor's standing in it: the checkmark travels with the
	// row, so no screen joins two lists. LearnerLessonSources does the join.
	// goverter:map Info.CourseLessonID ID
	// goverter:map Info.Edges.Lesson.Slug Slug
	// goverter:map Info.Name Name
	// goverter:map Info.Description Description
	// goverter:map Standing.Position Position
	// goverter:map Standing.Finished Finished
	ToLearnerLesson(source LearnerLessonSource) api.LearnerLesson

	ToLearnerLessons(source []LearnerLessonSource) []api.LearnerLesson

	// goverter:map Row.Edges.Version.ModuleID ID
	// goverter:map Row.Name Name
	// goverter:map Row.Description Description
	ToCourseModule(source ModuleSource) api.CourseModule

	ToCourseModules(source []ModuleSource) []api.CourseModule

	// The player payload, assembled from the rows in LessonContent. versionId and
	// version both carry the Lesson Version id, as the legacy serializer emitted
	// them (one from the Translation's FK column, one from the row it points at);
	// the check operation reads the former.
	// goverter:map Course Course
	// goverter:map Lesson.ID ID
	// goverter:map Lesson.Slug Slug
	// goverter:map Lesson.CreatedAt CreatedAt
	// goverter:map Translation.Name Name
	// goverter:map Translation.Locale Locale
	// goverter:map Translation.Description Description
	// goverter:map Translation.Instructions Instructions
	// goverter:map Translation.Theory Theory
	// goverter:map Translation.Definitions Definitions | lessonDefinitions
	// goverter:map Translation.Tips Tips | lessonTips
	// goverter:map Version.NaturalOrder NaturalOrder
	// goverter:map Version.ID VersionId
	// goverter:map Version.ID Version
	// goverter:map Version.PreparedCode PreparedCode
	// goverter:map Version.OriginalCode OriginalCode
	// goverter:map Version.TestCode TestCode
	// goverter:map . ExerciseExtension | exerciseExtension
	// goverter:map . TestExtension | testExtension
	// goverter:map SourceCodeURL SourceCodeUrl | sourceCodeURL
	ToCourseLesson(source LessonContent) api.CourseLesson
}

// CourseProgressSource is what a course's progress is computed from: the state
// and the lessons of the visitor's locale, which name the Next Lesson.
type CourseProgressSource struct {
	State   *progress.CourseState
	Lessons []api.LearnerLesson
}

// LearnerLessonSource is one lesson's translation with the visitor's standing
// in it.
type LearnerLessonSource struct {
	Info     *ent.CourseLessonTranslation
	Standing progress.LessonState
}

// LearnerLessonSources joins the lessons of a Version in one locale with the
// visitor's standing in each. infos are the translations in course order, each
// with its lesson loaded (WithLesson).
//
// A lesson the state does not know has no Position and is not finished: the
// state and the infos read the same Version, so that is a lesson added since
// the state was computed, not a case to fail on.
func LearnerLessonSources(infos []*ent.CourseLessonTranslation, state *progress.CourseState) []LearnerLessonSource {
	standing := make(map[string]progress.LessonState, len(state.Lessons))
	for _, lesson := range state.Lessons {
		standing[lesson.Slug] = lesson
	}
	return lo.Map(infos, func(info *ent.CourseLessonTranslation, _ int) LearnerLessonSource {
		slug := ""
		if info.Edges.Lesson != nil {
			slug = lo.FromPtr(info.Edges.Lesson.Slug)
		}
		return LearnerLessonSource{Info: info, Standing: standing[slug]}
	})
}

// ModuleSource is a module's translation with the lessons it lists.
type ModuleSource struct {
	Row     *ent.CourseModuleTranslation
	Lessons []api.LearnerLesson
}

// ModuleSources assigns each module its lessons. rows are the module
// translations with their lesson versions and lessons loaded (WithVersion,
// WithLessonVersions, WithLesson), lessons already in course order; lessons
// are the Version's LearnerLessons, from which each module takes its own. A
// module's lesson that is not translated into the locale is simply not listed,
// as in the flat list.
func ModuleSources(rows []*ent.CourseModuleTranslation, lessons []api.LearnerLesson) []ModuleSource {
	bySlug := lo.KeyBy(lessons, func(l api.LearnerLesson) string { return l.Slug })
	return lo.Map(rows, func(row *ent.CourseModuleTranslation, _ int) ModuleSource {
		return ModuleSource{
			Row: row,
			Lessons: lo.FilterMap(moduleLessonSlugs(row), func(slug string, _ int) (api.LearnerLesson, bool) {
				lesson, ok := bySlug[slug]
				return lesson, ok
			}),
		}
	})
}

// nextLessonOf names the Next Lesson of a course from its lessons.
func nextLessonOf(source CourseProgressSource) api.NilLessonRef {
	return NextLessonRef(source.State.NextLessonSlug, source.Lessons)
}

// dashboardNextLesson is null when the dashboard found no Next Lesson in the
// locale, else the reference the dashboard resolved.
func dashboardNextLesson(c dashboard.Course) api.NilLessonRef {
	if c.NextLesson == nil {
		return api.NilLessonRef{Null: true}
	}
	return NamedLessonRef(c.State.NextLessonSlug, c.NextLesson.ID, &c.NextLesson.Name)
}

// NextLessonRef names the Next Lesson from the lessons of the visitor's locale.
// Null when there is none, and when the lessons do not contain it: a lesson with
// no translation in the locale has no page there to point at.
func NextLessonRef(slug *string, lessons []api.LearnerLesson) api.NilLessonRef {
	if slug == nil {
		return api.NilLessonRef{Null: true}
	}
	for _, lesson := range lessons {
		if lesson.Slug == *slug {
			return api.NewNilLessonRef(lessonRef(lesson))
		}
	}
	return api.NilLessonRef{Null: true}
}

// NamedLessonRef is a reference to the lesson with slug and id, called name, for
// a caller that resolved them itself. Null when there is no slug.
func NamedLessonRef(slug *string, id int, name *string) api.NilLessonRef {
	if slug == nil {
		return api.NilLessonRef{Null: true}
	}
	return api.NewNilLessonRef(api.LessonRef{ID: int32(id), Slug: *slug, Name: NilStringFromPtr(name)})
}

func lessonRef(l api.LearnerLesson) api.LessonRef {
	return api.LessonRef{ID: l.ID, Slug: l.Slug, Name: l.Name}
}

// AdjacentLessons are the lessons on either side of the one with slug, in the
// order lessons are given: course order, whatever the learner has finished.
// Either is null at the edge of the course.
func AdjacentLessons(slug string, lessons []api.LearnerLesson) api.AdjacentLessons {
	adjacent := api.AdjacentLessons{
		Previous: api.NilLessonRef{Null: true},
		Next:     api.NilLessonRef{Null: true},
	}
	index := lo.IndexOf(lo.Map(lessons, func(l api.LearnerLesson, _ int) string { return l.Slug }), slug)
	if index < 0 {
		return adjacent
	}
	ref := func(l api.LearnerLesson) api.NilLessonRef {
		return api.NewNilLessonRef(lessonRef(l))
	}
	if index > 0 {
		adjacent.Previous = ref(lessons[index-1])
	}
	if index < len(lessons)-1 {
		adjacent.Next = ref(lessons[index+1])
	}
	return adjacent
}

// LessonContent is one Lesson as the player needs it, drawn from the three
// rows that hold it: the stable Lesson identity, the Version carrying the code
// and the tests, and the Translation carrying the prose for one locale.
//
// They are passed in rather than walked from an edge because only the caller
// knows which Version and which locale it resolved — the current Version and
// the request locale — and a converter that re-resolved them could disagree
// with the query that produced them.
type LessonContent struct {
	Course      *ent.Course
	Lesson      *ent.CourseLesson
	Version     *ent.CourseLessonVersion
	Translation *ent.CourseLessonTranslation

	// SourceCodeURL points at the Lesson's README in the content repository.
	// Built by the caller, which has the repository host in config.
	SourceCodeURL string
}

// exerciseExtension and testExtension: the build's own file names say what
// language the code and the tests are in; the course slug does not (the AI
// course is markdown with JS tests).
func exerciseExtension(c LessonContent) api.NilString {
	return nilExtension(lo.FromPtr(currentBuild(c).Extension))
}

func testExtension(c LessonContent) api.NilString {
	return nilExtension(filepath.Ext(lo.FromPtr(currentBuild(c).ExerciseTestFilename)))
}

func currentBuild(c LessonContent) *ent.CourseVersion {
	if c.Course == nil || c.Course.Edges.CurrentVersion == nil {
		return &ent.CourseVersion{}
	}
	return c.Course.Edges.CurrentVersion
}

// sourceCodeURL is never null: the caller always has the repository host.
func sourceCodeURL(v string) api.NilString { return api.NewNilString(v) }

// nilExtension is a bare extension (no dot) or null. The spec's `extension:` is
// already bare; a test filename is not, so callers pass the file's Ext. An empty
// value is null so the client falls back to the course slug instead of
// highlighting by a made-up language.
func nilExtension(ext string) api.NilString {
	ext = strings.TrimPrefix(ext, ".")
	if ext == "" {
		return api.NilString{Null: true}
	}
	return api.NewNilString(ext)
}

// lessonTips and lessonDefinitions decode the two columns the loader writes as
// YAML arrays, for compatibility with Rails' `serialize type: Array`.
//
// A column that does not decode yields nothing rather than failing the read: a
// lesson whose tips are malformed is a content defect, and refusing to render
// the theory over it would turn a cosmetic problem into an outage on a page
// that is also the one search engines index.
func lessonTips(raw *string) []string {
	tips := []string{}
	decodeLessonYAML(raw, &tips)
	return tips
}

func lessonDefinitions(raw *string) []api.LessonDefinition {
	var decoded []struct {
		Name        string `yaml:"name"`
		Description string `yaml:"description"`
	}
	decodeLessonYAML(raw, &decoded)

	definitions := make([]api.LessonDefinition, 0, len(decoded))
	for _, d := range decoded {
		definitions = append(definitions, api.LessonDefinition{Name: d.Name, Description: d.Description})
	}
	return definitions
}

func decodeLessonYAML(raw *string, into any) {
	if raw == nil || *raw == "" {
		return
	}
	_ = yaml.Unmarshal([]byte(*raw), into)
}

// NilEnrollmentStateFromPtr resolves the nullable legacy column to the contract's
// nilable enum: a learner with no Enrollment has no state at all, which is the
// "not started" condition rather than a state a record can be in.
func NilEnrollmentStateFromPtr(v *string) api.NilEnrollmentState {
	if v == nil || *v == "" {
		return api.NilEnrollmentState{Null: true}
	}
	return api.NewNilEnrollmentState(api.EnrollmentState(*v))
}

// NilEnrollmentStateFromString is the same for a computed state, which is a
// plain string and empty when the learner has no Enrollment.
func NilEnrollmentStateFromString(v string) api.NilEnrollmentState {
	return NilEnrollmentStateFromPtr(&v)
}

// TimeIdentity copies a time.Time as-is, so goverter treats it as a scalar
// instead of deep-copying its unexported fields.
func TimeIdentity(v time.Time) time.Time { return v }

// Int32FromInt narrows an ent int id/count to the contract's int32.
func Int32FromInt(v int) int32 { return int32(v) }

// Int32FromPtr resolves a nullable ent integer to a required contract field.
func Int32FromPtr(v *int) int32 { return int32(lo.FromPtr(v)) }

// StringFromPtr resolves a nullable ent column to a required string field.
func StringFromPtr(v *string) string { return lo.FromPtr(v) }

// EnrollmentStateFromPtr mirrors AASM's initial state for nullable legacy rows.
func EnrollmentStateFromPtr(v *string) api.EnrollmentState {
	if v == nil || *v == "" {
		return api.EnrollmentStateStarted
	}
	return api.EnrollmentState(*v)
}

// moduleLessonSlugs lists a module's lessons by slug, in the order the query
// loaded its lesson versions. A lesson with no slug has no URL to link, so it
// is left out rather than listed as an empty string.
func moduleLessonSlugs(source *ent.CourseModuleTranslation) []string {
	if source == nil || source.Edges.Version == nil {
		return []string{}
	}
	return lo.FilterMap(source.Edges.Version.Edges.LessonVersions, func(v *ent.CourseLessonVersion, _ int) (string, bool) {
		if v.Edges.Lesson == nil || v.Edges.Lesson.Slug == nil {
			return "", false
		}
		return *v.Edges.Lesson.Slug, true
	})
}

// lessonProgressLessonName reads the first eager-loaded localized info. The
// handler orders the edge by id so "first" is deterministic and matches the
// legacy Lesson#localed_info convention.
func lessonProgressLessonName(source *ent.LessonProgress) string {
	if source == nil || source.Edges.Lesson == nil || len(source.Edges.Lesson.Edges.Infos) == 0 {
		return ""
	}
	return StringFromPtr(source.Edges.Lesson.Edges.Infos[0].Name)
}

// assistantMessageLessonName resolves the lesson display name through
// chat → lesson progress → lesson → first eager-loaded localized info (the same
// convention as lessonProgressLessonName, which it reuses).
func assistantMessageLessonName(source *ent.AiMessage) string {
	if source == nil || source.Edges.Chat == nil || source.Edges.Chat.Edges.LessonProgress == nil {
		return ""
	}
	return lessonProgressLessonName(source.Edges.Chat.Edges.LessonProgress)
}

// nilSetter is what ogen's generated Nil* wrappers share: SetTo and SetToNull
// on a pointer receiver.
type nilSetter[V any, N any] interface {
	*N
	SetTo(V)
	SetToNull()
}

// nilOf bridges a nullable ent column to the ogen Nil wrapper N of its value
// type: null when v is nil, the value otherwise. Every NilXFromPtr below is
// this with the contract type spelled out.
func nilOf[V any, N any, P nilSetter[V, N]](v *V) N {
	var out N
	if v == nil {
		P(&out).SetToNull()
		return out
	}
	P(&out).SetTo(*v)
	return out
}

// nilStringAs retypes a nullable ent string as a contract enum (or any
// string-backed type), keeping nil as nil.
func nilStringAs[V ~string](v *string) *V {
	if v == nil {
		return nil
	}
	return lo.ToPtr(V(*v))
}

// nilEnumOf is nilOf for a nullable ent string that the contract types as an
// enum V.
func nilEnumOf[V ~string, N any, P nilSetter[V, N]](v *string) N {
	return nilOf[V, N, P](nilStringAs[V](v))
}

// nilInt32From narrows a nullable ent int to the contract's int32, keeping nil.
func nilInt32From(v *int) *int32 {
	if v == nil {
		return nil
	}
	return lo.ToPtr(int32(*v))
}

// NilStringFromPtr bridges a nullable ent column to ogen's NilString.
func NilStringFromPtr(v *string) api.NilString { return nilOf[string, api.NilString](v) }

// NilInt32FromPtr bridges a nullable ent int to ogen's NilInt32.
func NilInt32FromPtr(v *int) api.NilInt32 { return nilOf[int32, api.NilInt32](nilInt32From(v)) }

// NilBoolFromPtr bridges a nullable ent bool column to ogen's NilBool.
func NilBoolFromPtr(v *bool) api.NilBool { return nilOf[bool, api.NilBool](v) }

// NilDateTimeFromPtr bridges a nullable ent time column to ogen's NilDateTime.
func NilDateTimeFromPtr(v *time.Time) api.NilDateTime { return nilOf[time.Time, api.NilDateTime](v) }

// NilLearnAsFromPtr bridges a nullable ent string to ogen's NilCourseLearnAs.
func NilLearnAsFromPtr(v *string) api.NilCourseLearnAs {
	return nilEnumOf[api.CourseLearnAs, api.NilCourseLearnAs](v)
}

// NilReadinessFromPtr bridges a nullable ent string to ogen's NilCourseReadiness.
func NilReadinessFromPtr(v *string) api.NilCourseReadiness {
	return nilEnumOf[api.CourseReadiness, api.NilCourseReadiness](v)
}

// coverURLNull keeps CoverUrl null until course cover assets are re-uploaded.
func coverURLNull(*ent.CourseLandingPage) api.NilString {
	return api.NilString{Null: true}
}

// leadFullNameNull keeps Lead.FullName null until the User schema lands and the
// name can be derived from the associated user (legacy serializer behavior).
func leadFullNameNull(*ent.Lead) api.NilString {
	return api.NilString{Null: true}
}

// NilReviewStateFromPtr bridges a nullable ent string to ogen's NilReviewState.
func NilReviewStateFromPtr(v *string) api.NilReviewState {
	return nilEnumOf[api.ReviewState, api.NilReviewState](v)
}

// NilBlogPostStateFromPtr bridges a nullable ent state string to the contract's
// BlogPostState.
func NilBlogPostStateFromPtr(v *string) api.NilBlogPostState {
	return nilEnumOf[api.BlogPostState, api.NilBlogPostState](v)
}

// NilStringFromEmpty is a string that is null when empty: a post without a
// cover has no URL, not an empty one.
func NilStringFromEmpty(v string) api.NilString {
	if v == "" {
		return api.NilString{Null: true}
	}
	return api.NewNilString(v)
}

// LocaleFromPtr bridges a nullable ent locale column to the required contract
// Locale. A row without a locale becomes "", which no page section matches.
func LocaleFromPtr(v *string) api.Locale {
	return api.Locale(lo.FromPtr(v))
}

// NilReviewLocaleFromPtr bridges a nullable ent string to ogen's NilReviewLocale.
func NilReviewLocaleFromPtr(v *string) api.NilReviewLocale {
	return nilEnumOf[api.ReviewLocale, api.NilReviewLocale](v)
}

// joinName joins a first/last name pair with a single space, treating a nil
// component as empty — mirrors the Ruby `[first, last].join(" ")` serializers.
func joinName(first, last *string) string {
	return lo.FromPtr(first) + " " + lo.FromPtr(last)
}

// userName mirrors UserResource#name.
func userName(u *ent.User) api.NilString {
	return api.NewNilString(joinName(u.FirstName, u.LastName))
}

// userCanAccessAdmin mirrors UserResource#can_access_admin: an administrator or
// a staff member. The staff record is read from the edge, so only users loaded
// with it (the session and sign-in paths) report staff access.
func userCanAccessAdmin(u *ent.User) bool {
	return lo.FromPtr(u.Admin) || u.Edges.StaffMember != nil
}

// userCreatedAtAsTimestamp mirrors UserResource#created_at_as_timestamp (a Unix
// epoch used by the GTM/Wootric integration); always present.
func userCreatedAtAsTimestamp(u *ent.User) api.NilInt64 {
	return api.NewNilInt64(u.CreatedAt.Unix())
}

// userType is the constant "user" discriminator from UserResource.
func userType(*ent.User) api.UserType {
	return api.UserTypeUser
}

// reviewFullName mirrors ReviewResource#full_name: the review's own first/last
// name (the reviewer's display name, not the associated user's).
func reviewFullName(r *ent.Review) api.NilString {
	return api.NewNilString(joinName(r.FirstName, r.LastName))
}

// NilLandingPageStateFromPtr bridges a nullable ent string to ogen's
// NilLandingPageState.
func NilLandingPageStateFromPtr(v *string) api.NilLandingPageState {
	return nilEnumOf[api.LandingPageState, api.NilLandingPageState](v)
}

// courseDuration mirrors Language#duration: estimated hours from the lesson
// count (lessons_count * 15 minutes, integer-divided to hours). Guards nil
// because a listed landing page may reference a course absent from the current
// query (or fixture) set — then duration reads as 0, matching `|| 0` upstream.
func courseDuration(c *ent.Course) int32 {
	if c == nil {
		return 0
	}
	return int32(c.LessonsCount * 15 / 60)
}

// PermissionResourceFromString bridges the ent resource column (a plain string)
// to the api's PermissionResource enum.
func PermissionResourceFromString(v string) api.PermissionResource {
	return api.PermissionResource(v)
}

// LocalesFromPq bridges the native pg text-array column to the api's plain
// []string (pq.StringArray is a []string, but goverter needs the named-type
// conversion spelled out).
func LocalesFromPq(v pq.StringArray) []string {
	return []string(v)
}

// staffRolePermissionsCount is the size of the role's loaded permissions edge,
// mirroring StaffRoleResource#permissions_count, plus its declared grants: a
// role holding only grants must not read as having none.
func staffRolePermissionsCount(r *ent.StaffRole) int32 {
	return int32(len(r.Edges.Permissions) + len(r.Edges.Grants))
}

// grantNames lists the Permissions a role holds, by name and in a stable order.
// It is never nil: the contract's grants is a required array.
func grantNames(grants []*ent.StaffRoleGrant) []string {
	names := make([]string, 0, len(grants))
	for _, g := range grants {
		names = append(names, g.Permission)
	}
	slices.Sort(names)
	return names
}

// landingOutcomesImageNull keeps OutcomesImage null until the landing-page
// outcomes image is migrated to blob storage (same deferral as the course
// cover — see coverURLNull).
func landingOutcomesImageNull(*ent.CourseLandingPage) api.NilString {
	return api.NilString{Null: true}
}

// NilCourseVersionFromEnt bridges the current_version association to ogen's
// NilCourseVersion. Constructing the Nil wrapper is the part goverter cannot
// infer, and an extend cannot call back into the converter, so the small
// CourseVersion body is hand-mapped alongside it (CourseVersionFromEnt) and
// stays one bridge rather than a generated method plus a wrapper.
func NilCourseVersionFromEnt(v *ent.CourseVersion) api.NilCourseVersion {
	if v == nil {
		return api.NilCourseVersion{Null: true}
	}
	return api.NewNilCourseVersion(CourseVersionFromEnt(v))
}

// CourseVersionFromEnt maps an ent course version to the API body. Used both by
// the current-version bridge above and by the createVersion handler (which
// returns a bare CourseVersion for the 201).
func CourseVersionFromEnt(v *ent.CourseVersion) api.CourseVersion {
	return api.CourseVersion{
		ID:        int32(v.ID),
		Name:      NilStringFromPtr(v.Name),
		Result:    NilStringFromPtr(v.Result),
		State:     NilStringFromPtr(v.State),
		CreatedAt: v.CreatedAt,
	}
}

// repositoryURL derives the exercises repo URL from the course slug, mirroring
// Language#repository_url. It is always present (the legacy method never returns
// nil), so the nullable API field carries a value.
func repositoryURL(c *ent.Course) api.NilString {
	return api.NewNilString("https://github.com/hexlet-basics/exercises-" + lo.FromPtr(c.Slug))
}

// hexletProgramLandingPage applies the legacy `.presence` semantics: a blank
// column reads as null rather than an empty string.
func hexletProgramLandingPage(c *ent.Course) api.NilString {
	if c.HexletProgramLandingPage == nil || *c.HexletProgramLandingPage == "" {
		return api.NilString{Null: true}
	}
	return api.NewNilString(*c.HexletProgramLandingPage)
}

// ratingCount reproduces the legacy serializer's placeholder rating count. The
// real aggregate over reviews is not implemented yet (the legacy code carries
// the same TODO); this keeps parity until it is.
func ratingCount(*ent.Course) int32 { return 89 }

// ratingValue reproduces the legacy serializer's placeholder rating: a fixed
// value keyed off id parity, pending a real reviews aggregate.
func ratingValue(c *ent.Course) float64 {
	if c.ID%2 == 0 {
		return 4
	}
	return 5
}

// coverVariantNull keeps the cover variant URLs null until course cover assets
// are migrated to blob storage (same deferral as coverURLNull).
func coverVariantNull(*ent.Course) api.NilString {
	return api.NilString{Null: true}
}
